import { EVENT_DETAILS } from './event-details.js';

// Original study material mapped to the 2026–27 HOSA event blueprints.
// Clinical procedures are simulation learning, not authorization to practice.
const slug = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
export const COURSES_TWO = {};
const courses = COURSES_TWO;
const references = {
 'Medical Terminology':[{title:'OpenStax Anatomy and Physiology 2e',url:'https://openstax.org/details/books/anatomy-and-physiology-2e'}],
 'Nutrition':[{title:'NIH Office of Dietary Supplements: nutrient fact sheets',url:'https://ods.od.nih.gov/factsheets/list-all/'}],
 'World Health & Disparities':[{title:'WHO: health equity',url:'https://www.who.int/health-topics/health-equity'},{title:'Our World in Data: health',url:'https://ourworldindata.org/health-meta'}],
 'Biotechnology':[{title:'OpenStax Biology 2e',url:'https://openstax.org/details/books/biology-2e'}],
 'Clinical Lab Science (Medical Lab Scientist)':[{title:'OpenStax Microbiology',url:'https://openstax.org/details/books/microbiology'}],
 'Clinical Nursing':[{title:'OpenStax Fundamentals of Nursing',url:'https://openstax.org/details/books/fundamentals-nursing'}],
 'Clinical Specialty':[{title:'ExploreHealthCareers: career exploration',url:'https://explorehealthcareers.org/'}],
 'Dental Science':[{title:'CDC: dental infection prevention and control',url:'https://www.cdc.gov/dental-infection-control/'}]
};
// Shared by later course files: compact lesson tuples become full lesson objects.
export function courseFrom(name, units, refs = references[name] || []) {
  return { units: units.map(([title, context, lessons]) => ({ title, lessons: lessons.map((d, i) => {
    const [lessonTitle, foundation, reasoning, application, nodes, q1, q2] = d;
    const nodeObjects = nodes.map(([label, detail]) => ({label, detail}));
    return {
      id: `${slug(name)}-${slug(lessonTitle)}`, title: lessonTitle, minutes: 18,
      objectives: [`Explain ${nodes[0][0].toLowerCase()} in context.`, `Distinguish ${nodes[1][0].toLowerCase()} from related concepts.`, `Apply ${nodes[2][0].toLowerCase()} to the worked case.`],
      sections: [{title:'Where this fits',paragraphs:[context]}, {title:'Build the concept',paragraphs:[foundation]}, {title:'Reason through the details',paragraphs:[reasoning]}, {title:'Connect the concepts',paragraphs:nodeObjects.map(n=>`${n.label}: ${n.detail}`)}],
      example:{prompt:application[0],explanation:application[1]},
      diagram:{title:lessonTitle+' · concept map',nodes:nodeObjects},
      mcqs:[q1,q2].map((q,j)=>{const answer=(i+j+1)%4;const options=q[1].slice();const correct=options.shift();options.splice(answer,0,correct);return {prompt:q[0],options,answer,explanation:q[2]};}),
      frq:{prompt:`${application[0]} Explain your reasoning using ${nodes.map(n=>n[0].toLowerCase()).join(', ')}. Connect each concept to the case rather than simply listing definitions.`,rubric:nodes.map(([label,detail,keywords])=>({label,keywords:keywords||label.toLowerCase().split(/\s+/)})),modelAnswer:application[1]+' '+nodes.map(n=>n[1]).join(' ')},
      sources:[{title:`HOSA 2026–27 ${name} guidelines and official reference list`,url:EVENT_DETAILS[name]?.source||'https://hosa.org/guidelines/'},...refs]
    };
  })}))};
}
const course = (name, units) => { courses[name] = courseFrom(name, units); };

course('Nutrition',[
 ['Unit 1 · Nutrients and energy','The Nutrition blueprint allocates 15% to macronutrients and 15% to vitamins and minerals. Learn what each nutrient does, how it is obtained and absorbed, and what deficiency or excess changes. Nutrition reasoning connects food patterns with physiology; a single food, supplement, or laboratory value does not describe the whole diet.',[
 ['Carbohydrate, protein, and fat','Carbohydrates include sugars, starches, and fiber. Digestible carbohydrate supplies about 4 kcal/g. Fiber is not digested like starch and can influence stool bulk, microbial metabolism, glucose response, and satiety. Protein also supplies about 4 kcal/g but has structural, transport, immune, and enzyme functions. Essential amino acids must come from the diet; complementary foods can collectively supply them. Fat supplies about 9 kcal/g, supports membranes, and helps absorb vitamins A, D, E, and K.','Saturated and unsaturated describe fatty-acid structure, not whether a food is morally good or bad. Evaluate an overall pattern, replacing rather than merely adding foods. Energy density and nutrient density differ: a food may contain much energy with few micronutrients. Protein needs vary with development and health; consuming more protein does not automatically build muscle. Energy calculations use the grams of each macronutrient, not the serving’s total mass.', ['A snack contains 20 g carbohydrate, 8 g protein, and 6 g fat. Calculate its estimated energy and explain one limitation.','Carbohydrate contributes 80 kcal, protein 32 kcal, and fat 54 kcal, totaling 166 kcal. The estimate does not reveal fiber, micronutrients, sodium, or dietary context.'],[['Carbohydrate','Twenty grams at 4 kcal/g contributes 80 kcal.',['80','carbohydrate']],['Protein','Eight grams at 4 kcal/g contributes 32 kcal and supplies amino acids.',['32','protein']],['Fat','Six grams at 9 kcal/g contributes 54 kcal.',['54','fat']]],['Which macronutrient provides approximately 9 kcal/g?',['Fat','Protein','Digestible carbohydrate','Water'],'Fat provides more than twice the energy per gram of protein or carbohydrate.'],['What does nutrient density describe?',['Nutrients relative to energy or amount of food','Only calories per gram','A food’s physical weight','Only protein content'],'Nutrient density reflects useful nutrients relative to the amount or energy consumed.']],
 ['Vitamins, minerals, and interacting deficiencies','Vitamins are organic compounds required in small quantities; minerals are elements. Fat-soluble vitamins can accumulate, so supplement excess can be harmful. Water-soluble vitamins are not automatically harmless at high doses. Vitamin C supports collagen and enhances nonheme iron absorption. Vitamin D supports calcium absorption; calcium contributes to bone, muscle, and signaling. Iron supports oxygen transport, while iodine supports thyroid hormone synthesis.','Deficiency signs can overlap. Fatigue alone does not prove iron deficiency; intake, absorption, blood loss, inflammation, and laboratory assessment matter. Vitamin B12 requires a functioning absorption pathway that includes intrinsic factor and the terminal ileum. Folate and B12 both affect cell production, but replacing folate alone may fail to address B12-related neurological injury. Compare recommended intake, tolerable upper limits, and therapeutic dosing as separate concepts. Food-first planning considers affordability, preferences, and restrictions.', ['A person eating no animal products wants a reliable B12 strategy. Explain what must be considered.','Vitamin B12 is required for neurological function and blood-cell production. A reliable fortified-food or supplement source may be needed, and absorption problems can require clinical evaluation. A varied plant diet alone does not guarantee adequate B12.'],[['B12','B12 supports nervous-system function and normal blood-cell production.',['b12','blood','nerve']],['Source','Fortified foods or appropriate supplementation provide reliable B12 sources.',['fortif','supplement']],['Absorption','Intrinsic factor and intestinal function affect absorption independently of intake.',['intrinsic','absorp','ileum']]],['Which vitamin enhances nonheme iron absorption?',['Vitamin C','Vitamin K','Vitamin D','Vitamin A'],'Vitamin C can improve absorption of iron from plant foods.'],['Which pair is directly linked in intestinal mineral absorption?',['Vitamin D and calcium','Vitamin K and sodium','Vitamin C and iodine','Vitamin A and chloride'],'Vitamin D helps regulate intestinal calcium absorption.']]
 ]],
 ['Unit 2 · Digestion and fluid balance','Digestion, absorption, and metabolism account for 10% of the blueprint and water/electrolyte balance another 10%. Distinguish breaking food into smaller molecules from moving those molecules across the intestine. Fluid distribution depends on both water and dissolved solutes, so replacing water alone is not always equivalent to replacing losses.',[
 ['From digestion to metabolism','Mechanical digestion includes chewing and mixing; chemical digestion uses enzymes to split molecules. Salivary amylase begins starch digestion. Stomach acid unfolds proteins and supports pepsin action. In the small intestine, pancreatic enzymes and intestinal processes complete much digestion. Bile emulsifies fat, increasing surface area; bile is not an enzyme. Villi and microvilli expand absorptive surface.','Most simple sugars and amino acids enter portal circulation toward the liver. Much absorbed dietary fat is packaged into chylomicrons that enter lymph before blood. The liver stores and transforms nutrients and helps stabilize blood glucose. Insulin supports nutrient storage after a meal; glucagon supports glucose availability during fasting. Malabsorption can occur even with adequate intake. A damaged intestinal surface can cause nutrient deficits and osmotic diarrhea, linking digestive disease to fluid balance.', ['Why can damage to intestinal villi cause poor nutrition despite adequate food intake?','Reduced absorptive surface limits nutrient transfer into the body. Undigested or unabsorbed material can retain water in the intestine, contributing to diarrhea. Intake, digestion, and absorption must all be assessed.'],[['Digestion','Enzymes break larger molecules into absorbable components.',['enzyme','break']],['Absorption','Villi provide surface for nutrient movement across intestinal cells.',['villi','surface']],['Metabolism','The liver and other tissues store, transform, and use absorbed nutrients.',['liver','use','store']]],['What is the primary digestive role of bile?',['Emulsifying fat','Digesting protein into amino acids','Producing insulin','Absorbing iron directly'],'Bile disperses fat droplets so enzymes can act more effectively.'],['Where does most nutrient absorption occur?',['Small intestine','Esophagus','Mouth','Rectum'],'The small intestine has extensive absorptive surface.']],
 ['Water, sodium, potassium, and osmosis','Water is distributed between intracellular and extracellular spaces. Sodium is a major extracellular cation and potassium a major intracellular cation. Osmosis moves water across a selectively permeable membrane toward a higher effective solute concentration. Kidneys, thirst, antidiuretic hormone, and aldosterone participate in regulation. Dehydration and low circulating volume are related but not identical concepts.','Fluid assessment combines intake and output, weight trends, symptoms, examination, and laboratory data. Rapid body-weight change can reflect fluid rather than tissue. Diarrhea and vomiting remove both water and electrolytes. Excess plain water can dilute sodium in some circumstances; conversely, dehydration can concentrate it. Potassium disturbances can affect cardiac conduction. Avoid memorizing one fixed fluid target for everyone: age, climate, activity, kidney function, and disease alter needs.', ['A simulated patient loses fluid through repeated diarrhea. Why is the problem more than thirst?','Diarrhea removes fluid and electrolytes and may reduce circulating volume. Replacement must consider both water and solute losses; urine output, symptoms, weight, and laboratory findings help assess response. Severe disturbances require clinical care.'],[['Osmosis','Water distribution depends on effective solute concentrations across membranes.',['solute','water']],['Electrolytes','Sodium and potassium support fluid balance, nerve activity, and muscle function.',['sodium','potassium']],['Monitoring','Trends in intake, output, weight, and clinical findings are more informative than thirst alone.',['output','weight','trend']]],['Which ion is predominantly intracellular?',['Potassium','Sodium','Chloride','Bicarbonate'],'Potassium is the principal intracellular cation.'],['A rapid weight change over one day most directly raises concern about what?',['Fluid balance','Bone length','New muscle mass','Vitamin stores'],'Short-term changes often reflect fluid shifts.']]
 ]],
 ['Unit 3 · Food across lives and cultures','Nutrition through the lifespan accounts for 15%, cultural patterns 5%, and food-related illness, intolerances, and allergies 10%. Needs change with development and illness, but planning must also respect family practices, access, culture, and personal choice. Distinguish biological requirements from assumptions based on someone’s identity.',[
 ['Pregnancy, childhood, aging, and access','Growth increases the need for sufficient energy and nutrients. Pregnancy changes requirements for several nutrients, including folate and iron, while infancy requires developmentally appropriate feeding. Young children have small stomach capacity and depend on adults for safe, varied food. Adolescence combines growth with increasing autonomy and social influences. Older adults may have lower energy needs yet continuing or increased vulnerability to nutrient deficits.','Aging can involve medication effects, swallowing difficulty, dental problems, reduced appetite, limited mobility, and social isolation. Evaluate barriers before labeling a person nonadherent. Cultural preferences can be incorporated by modifying familiar meals instead of imposing unfamiliar ones. Food insecurity concerns unreliable access to sufficient food; it can coexist with higher body weight. A useful plan considers budget, cooking facilities, transportation, chewing ability, and who buys or prepares meals.', ['An older adult skips meals because of painful dentures and no transportation. Explain an appropriate nutrition assessment.','Assess chewing difficulty, intake, weight trend, hydration, and access. Dental evaluation, acceptable softer nutrient-dense foods, and transportation or meal resources address specific barriers. Simply instructing the person to eat more overlooks the causes.'],[['Life stage','Older adults may need nutrient-dense foods despite lower total energy needs.',['older','nutrient']],['Access','Transportation, cost, and food preparation affect what is feasible.',['transport','cost','access']],['Function','Chewing and swallowing capacity influence safe food choices.',['chew','swallow','denture']]],['Which statement about food insecurity is accurate?',['It can coexist with higher body weight','It occurs only with visible wasting','It means disliking vegetables','It is corrected solely by vitamin pills'],'Unreliable food access does not have one characteristic body size.'],['Which plan best respects cultural food practices?',['Adapt familiar foods to nutritional needs','Replace all familiar foods','Assume every person in a group eats alike','Ignore cost and availability'],'Individualized planning preserves acceptable foods while addressing needs.']],
 ['Allergy, intolerance, and foodborne illness','Food allergy involves an immune response; intolerance can involve enzyme deficiency or other nonimmune mechanisms. Lactose intolerance results from inadequate lactose digestion and may cause gas, bloating, and diarrhea. Celiac disease is an immune-mediated response to gluten with intestinal injury, not simply a preference or ordinary intolerance. Foodborne infection involves organisms, while intoxication can result from toxins already present in food.','Prevent cross-contact for allergens and cross-contamination for pathogens. Hand hygiene, separate equipment, safe temperatures, appropriate storage, and reliable sourcing work together. Cooking may kill organisms without eliminating every toxin or allergen. A label must be read each time because formulations change. In a case question, distinguish immediate systemic symptoms from delayed gastrointestinal discomfort. Do not use a classroom challenge or tasting experiment to test whether an allergy is real.', ['A student says lactose intolerance and milk allergy require identical reasoning. Explain the distinction.','Lactose intolerance concerns digestion of milk sugar, whereas milk allergy is an immune reaction to milk proteins. Avoidance and emergency planning depend on the actual condition. Lactose-free milk may still contain milk proteins and therefore is not automatically safe for milk allergy.'],[['Immune response','Allergy involves immune recognition of a food component.',['immune','protein']],['Enzyme','Lactase deficiency impairs lactose digestion.',['lactase','lactose']],['Cross-contact','Allergen transfer can occur even when the ingredient is not intentionally included.',['allergen','contact','transfer']]],['Why may lactose-free milk be unsuitable for milk allergy?',['It can still contain milk proteins','It always contains more lactose','It contains no nutrients','Lactose is a bacterium'],'Removing lactose does not necessarily remove allergenic proteins.'],['Which action prevents microbial cross-contamination?',['Separate raw-food utensils from ready-to-eat food','Use one unwashed board for all food','Rely only on appearance','Leave food unrefrigerated overnight'],'Separating equipment prevents transfer of organisms.']]
 ]],
 ['Unit 4 · Medical nutrition reasoning','Medical nutrition therapy accounts for 20% of the blueprint and includes diabetes, renal, cardiovascular, gastrointestinal, cancer, and special needs. Study the rationale behind adaptations rather than prescribing a universal diet. Disease stage, medications, laboratory values, symptoms, and patient priorities determine the appropriate plan.',[
 ['Diabetes and cardiovascular patterns','Carbohydrate amount, distribution, and food context influence blood glucose after meals. Fiber-rich foods and balanced meals can support a sustainable pattern. Medication timing and activity also affect glucose, so skipping a meal can have different implications for different treatments. Diabetes management cannot be reduced to avoiding all carbohydrates or all fruit.','For cardiovascular health, examine saturated fat replacement, sodium, fiber, total energy, and dietary patterns. Replacing saturated fat with unsaturated fat differs from replacing it with refined carbohydrate. Sodium reduction can support blood-pressure management for many people but must fit the clinical plan. Teach label comparison per actual serving, not just per package. A product described as low fat can still be high in added sugar or sodium.', ['Two products have identical calories, but one has more fiber and less sodium. How should they be compared for a person with diabetes and hypertension?','Consider serving size, total carbohydrate, fiber, sodium, overall meal pattern, medication timing, and preferences. Equal calories do not imply equal glucose response or cardiovascular relevance. Select within an individualized plan.'],[['Carbohydrate','Total amount and distribution matter for post-meal glucose.',['carbohydrate','glucose']],['Sodium','Sodium intake can affect blood-pressure management.',['sodium','pressure']],['Pattern','Whole meals and sustainable substitutions matter beyond a single nutrient claim.',['pattern','meal','serving']]],['What is essential when comparing nutrition labels?',['Use comparable actual serving sizes','Compare package colors','Ignore portions','Look only for low-fat claims'],'Nutrient amounts depend on the portion consumed.'],['Which replacement changes fat quality?',['Replacing some saturated fat with unsaturated fat','Adding sugar without changing fat','Removing all protein','Doubling portions'],'The kind of replacement matters, not merely lowering one nutrient.']],
 ['Renal, gastrointestinal, and cancer nutrition','Kidney disease can impair handling of fluid, potassium, phosphorus, and metabolic wastes. Needs differ by stage and dialysis status; a restriction appropriate for one person can be inappropriate for another. Protein requirements in dialysis differ from some nondialysis plans. Laboratory trends and a renal dietitian’s assessment guide decisions.','Gastrointestinal disease may reduce intake, digestion, or absorption. Cancer and treatment may produce nausea, taste changes, mouth pain, early satiety, and weight loss. The first question is which barrier limits intake and what safe adaptation addresses it. Texture modification, smaller meals, nutrition support, or symptom management may be appropriate under supervision. A feeding route must be selected according to gastrointestinal function and aspiration risk. Avoid applying a restrictive disease diet so broadly that inadequate energy and protein become the dominant problem.', ['A renal patient also has poor appetite during cancer treatment. Why is a blanket low-protein diet inadequate reasoning?','Kidney disease stage, dialysis, laboratory findings, treatment, and current nutrition status must be evaluated together. The person may be at risk of inadequate intake and muscle loss. An individualized interdisciplinary plan balances metabolic concerns with nutritional needs.'],[['Renal stage','Dietary targets depend on kidney function and dialysis status.',['dialysis','stage','kidney']],['Intake barrier','Nausea, pain, taste change, and early satiety can reduce intake.',['nausea','appetite','intake']],['Individualization','Laboratory trends, symptoms, and nutrition status guide the plan.',['individual','laboratory','status']]],['Why do renal dietary instructions vary?',['Disease stage and treatment change nutrient handling','All kidneys fail identically','Only food color matters','Dialysis never changes needs'],'Stage, dialysis, and laboratory values affect appropriate recommendations.'],['Which finding is a direct barrier to eating?',['Painful mouth sores','A preference recorded accurately','A stable meal schedule','Reliable food access'],'Mouth pain can limit intake and needs targeted management.']]
 ]]
]);

course('Medical Terminology',[
 ['Unit 1 · Construct and decode medical language','Word roots, prefixes, suffixes, and combining forms make up 45% of this event’s test plan. A word-part strategy is therefore the foundation, but it is not a substitute for checking a medical dictionary. Clinical meaning can be more specific than a literal translation. Learn the spelling, pronunciation, and context together; the current event also uses correctly spelled written tiebreaker responses.',[
  ['Roots, combining vowels, and suffixes','A root supplies a core meaning: cardi refers to the heart, gastr to the stomach, and neur to a nerve. A combining form adds a vowel, usually o, so cardi/o can join another part. A suffix commonly identifies a condition, procedure, or discipline. In cardiology, cardi/o identifies the heart and -logy identifies a field of study. Gastritis instead joins gastr to the vowel-starting suffix -itis without the combining o. When two roots join, the combining vowel often remains, as in osteoarthritis. These are useful patterns, not universal spelling laws.','Decode from the suffix toward the beginning, then reconstruct a natural definition. Gastroenteritis means inflammation of the stomach and intestines, not a procedure to examine them. Distinguish -ectomy, removal; -otomy, incision; and -ostomy, a surgically created opening. A colostomy does not necessarily remove the entire colon. Record established definitions for terms whose clinical meaning exceeds their parts, and use a dictionary for exceptions. Practice producing the term from a plain-language definition as well as recognizing it in an answer choice.', ['A chart mentions a gastrectomy and a gastrostomy. Explain why the words cannot be substituted.','Both refer to the stomach. Gastrectomy describes surgical removal of some or all stomach tissue, while gastrostomy describes creation of an opening into the stomach. The suffix changes the clinical action and therefore the meaning of the record.'],[['Root','Gastr identifies the stomach; the organ stays the same in both terms.',['gastr','stomach']],['Suffix','-ectomy indicates removal; -ostomy indicates a created opening.',['removal','opening']],['Combining form','Gastr/o joins word parts, but the combining vowel is often dropped before a vowel-starting suffix.',['vowel','combining']]],['Which suffix describes surgical incision?',['-otomy','-ectomy','-itis','-logy'],'An incision cuts into a structure; removal is -ectomy.'],['Which is the best interpretation of neuritis?',['Inflammation of a nerve','Removal of a nerve','Study of nerves','Imaging of a nerve'],'Neur identifies a nerve and -itis indicates inflammation.']],
  ['Prefixes, opposites, and spelling precision','Prefixes modify location, number, speed, quantity, or direction. Hyper- means excessive or above a reference level, while hypo- means below or deficient. Tachy- and brady- contrast fast and slow. Intra- means within; inter- means between. Peri- means around and endo- means within. A- and an- can indicate absence, but not every initial a belongs to that prefix. In anemia, for example, the established definition concerns reduced hemoglobin or red-cell capacity, not literally the complete absence of blood.','Contrast confusing pairs in a sentence: ileum is part of the small intestine, while ilium is part of the pelvis. Ureter carries urine from a kidney toward the bladder; urethra carries urine outward. Dys- means difficult, painful, or abnormal, whereas dis- often signifies separation or reversal. A pronunciation clue does not guarantee the spelling. Write an unfamiliar term in parts, verify the final word, then retrieve it without copying. Avoid inventing plurals by adding s: vertebra becomes vertebrae and diagnosis becomes diagnoses.', ['Explain why hypoglycemia and hyperglycemia describe opposite directions of the same variable.','Glyc refers to sugar and -emia to a blood condition. Hypo- indicates a low concentration, while hyper- indicates a high concentration. Neither term alone establishes the cause, severity, or treatment.'],[['Prefix','Hypo- and hyper- specify direction relative to a reference level.',['hypo','hyper']],['Root','Glyc refers to sugar rather than oxygen or blood pressure.',['sugar','glucose']],['Context','A term names a finding; clinical interpretation requires values, symptoms, and circumstances.',['context','value','symptom']]],['Which prefix means between?',['Inter-','Intra-','Endo-','Peri-'],'Intercostal means between ribs; intra- means within.'],['Which spelling identifies the pelvic bone?',['Ilium','Ileum','Ileus','Illeum'],'Ilium is bone; ileum is intestine, and ileus is impaired intestinal transit.']]
 ]],
 ['Unit 2 · Body organization and support','The blueprint includes body overview, skeletal, muscular, and integumentary terminology. Link each term to a structure, function, and potential disorder. Anatomical position provides a shared reference even when a patient changes position. Do not infer a diagnosis solely from a word’s appearance: similar roots can identify very different tissues.',[
 ['Anatomical directions, planes, and cavities','Anatomical position places the person upright, facing forward, with palms forward. Anterior means toward the front and posterior toward the back. Superior and inferior indicate toward the head and feet; medial and lateral refer to distance from the midline. Proximal and distal are especially useful on limbs: the elbow is proximal to the wrist. Superficial and deep describe depth. Right and left always belong to the person being described, not the observer.','A sagittal plane divides right and left portions; a midsagittal plane creates equal halves. A frontal plane separates anterior and posterior portions, while a transverse plane separates superior and inferior portions. The dorsal cavity includes cranial and vertebral spaces. The ventral cavity includes thoracic and abdominopelvic spaces, with the diaphragm separating the thoracic from abdominal region. The peritoneum is a membrane associated with abdominal organs; retroperitoneal structures lie behind it. Translate location statements into a sketch before memorizing them.', ['Describe the wrist relative to the elbow and a transverse section relative to a frontal section.','The wrist is distal to the elbow because it is farther from the limb’s attachment. A transverse section separates upper and lower portions, while a frontal section separates front and back portions. All descriptions use the patient’s anatomical orientation.'],[['Distal','Farther from the point of attachment, such as wrist relative to elbow.',['distal','attachment']],['Transverse','A cross-sectional plane separating superior and inferior portions.',['superior','inferior','transverse']],['Frontal','A plane separating anterior and posterior portions.',['anterior','posterior','frontal']]],['The sternum is what relative to the spine?',['Anterior','Posterior','Distal','Inferior'],'In anatomical position the sternum lies in front of the vertebral column.'],['Which plane divides right and left portions?',['Sagittal','Frontal','Transverse','Horizontal'],'Sagittal planes divide right and left, with midsagittal denoting equal halves.']],
 ['Bone, muscle, skin, and movement','Oste/o identifies bone, arthr/o a joint, chondr/o cartilage, and my/o muscle. Osteoporosis concerns reduced bone strength and increased fracture risk; osteoarthritis concerns degeneration of joint structures. Myalgia means muscle pain, while myopathy means muscle disease. Tendons connect muscle to bone; ligaments commonly connect bone to bone. Flexion usually decreases a joint angle and extension increases it. Abduction moves away from the body’s midline; adduction moves toward it.','Dermat/o and cutane/o refer to skin. Epidermis is the outer epithelial layer; dermis contains connective tissue, vessels, glands, and sensory structures. Subcutaneous tissue lies beneath the skin. A macule is flat, a papule is raised, and a vesicle contains fluid. Ecchymosis describes bruising and erythema describes redness; neither word identifies the cause. When interpreting a term, separate tissue from process: dermatitis indicates inflammation of skin while dermatoplasty concerns surgical repair. Do not replace precise morphology with vague words such as rash when the task asks for a lesion type.', ['A note describes myalgia, erythema, and limited abduction. Translate each finding without inventing a diagnosis.','The person reports muscle pain, has observed redness, and has restricted movement away from the midline. These are different kinds of findings: symptom, appearance, and movement limitation. They do not by themselves establish the underlying disease.'],[['Myalgia','Muscle pain is a symptom and does not automatically mean muscle inflammation.',['muscle','pain']],['Erythema','Redness is an observable appearance with multiple potential causes.',['redness','skin']],['Abduction','Movement away from the midline contrasts with adduction toward it.',['away','midline']]],['Which word part identifies cartilage?',['Chondr/o','Oste/o','Dermat/o','My/o'],'Chondr/o refers to cartilage.'],['Which lesion is fluid-filled?',['Vesicle','Macule','Ecchymosis','Scar'],'A vesicle is a small fluid-filled lesion; a macule is flat.']]
 ]],
 ['Unit 3 · Transport, respiration, and digestion','Respiratory, digestive, cardiovascular, and lymphatic systems each appear in the terminology blueprint. Follow a material through the body: air reaches alveoli, blood transports gases and nutrients, and digestion supplies absorbable molecules. This functional framework makes similar vocabulary easier to separate and prevents memorizing isolated labels without meaning.',[
 ['Cardiovascular, lymphatic, and respiratory vocabulary','Cardi/o means heart, angi/o vessel, arteri/o artery, and phleb/o or ven/o vein. Arteries carry blood away from the heart and veins return it; oxygen content is not the defining distinction. Pulmonary arteries carry relatively deoxygenated blood toward the lungs. Hemat/o refers to blood and thromb/o to a clot. A thrombus forms within a vessel or heart chamber; an embolus travels through circulation. Lymph/o relates to lymph, and lymphaden/o identifies lymph nodes.','Pneum/o can refer to lung or air, bronch/o to bronchus, and alveol/o to an alveolus. Dyspnea means difficult or uncomfortable breathing, apnea a temporary absence of breathing, and tachypnea an increased breathing rate. Hypoxemia is low oxygen in arterial blood; hypoxia is inadequate oxygen at tissue level. Hemoptysis is coughing up blood from the respiratory tract, whereas hematemesis is vomiting blood. A pulse oximetry estimate and a blood pressure measurement describe different variables; never merge their terminology.', ['Why can a pulmonary artery carry oxygen-poor blood while still being an artery?','Arteries are defined by direction away from the heart. The pulmonary artery carries blood from the right ventricle toward lung capillaries, where gas exchange occurs. Oxygen content changes after that exchange, but the vessel’s classification does not.'],[['Artery','A vessel carrying blood away from the heart, regardless of oxygen content.',['away','heart']],['Pulmonary','A modifier identifying the lung circulation.',['lung','pulmonary']],['Gas exchange','Alveolar exchange increases oxygen content and removes carbon dioxide.',['oxygen','carbon','alveol']]],['Which term means coughing up blood?',['Hemoptysis','Hematemesis','Hematuria','Melena'],'Hemoptysis is respiratory; hematemesis is vomiting blood.'],['Which term specifically refers to low arterial blood oxygen?',['Hypoxemia','Hypoglycemia','Hypercapnia','Anemia'],'Hypoxemia names low blood oxygen; hypoxia refers to tissues.']],
 ['Digestive and urinary pathways','The alimentary canal runs from mouth through pharynx, esophagus, stomach, small intestine, and large intestine. Stomat/o identifies mouth, esophag/o esophagus, gastr/o stomach, enter/o intestine, and col/o colon. Hepat/o refers to liver, chol/e to bile, cholecyst/o to gallbladder, and pancreat/o to pancreas. Dysphagia means difficulty swallowing; dyspepsia is indigestion. An endoscopy examines an internal space, but the complete term tells you which route and organ are involved.','Nephr/o and ren/o refer to kidney. Pyel/o refers to the renal pelvis, ureter/o to ureter, cyst/o often to urinary bladder, and urethr/o to urethra. Urine passes kidney, ureter, bladder, then urethra. Polyuria means increased urine volume, not simply frequent small voids. Oliguria is reduced urine output and anuria is essentially absent output. Hematuria is blood in urine, whereas proteinuria is protein in urine. A suffix such as -uria identifies a urine-related condition, but values and clinical context are still needed to interpret significance.', ['A learner confuses dysphagia with dysuria and the ureter with the urethra. Correct the confusion using the pathways.','Dysphagia concerns swallowing along the digestive pathway; dysuria concerns painful or difficult urination. The ureter carries urine from kidney to bladder, while the urethra carries it from bladder toward the exterior. Similar spelling does not make the structures interchangeable.'],[['Dysphagia','Difficulty swallowing involves the mouth, pharynx, or esophagus.',['swallow']],['Ureter','The paired ureters connect kidneys to the bladder.',['kidney','bladder']],['Urethra','The urethra carries urine outward from the bladder.',['out','bladder']]],['Which combining form identifies the liver?',['Hepat/o','Nephr/o','Cyst/o','Gastr/o'],'Hepat/o refers to liver; nephro refers to kidney.'],['Polyuria describes which finding?',['Increased urine volume','Blood in urine','Pain on swallowing','Urinary stones'],'Poly- means much and -uria relates to urine; frequency and total volume differ.']]
 ]],
 ['Unit 4 · Regulation, reproduction, and clinical meaning','Nervous and special senses, endocrine, and reproductive terms complete the major body systems in the event blueprint. Connect terminology to control pathways and anatomy. Disease names, procedures, specialists, and symptoms belong to different categories. A strong response states the category and meaning precisely without attaching unsupported clinical conclusions.',[
 ['Nervous, special senses, and endocrine language','The central nervous system includes brain and spinal cord; peripheral nerves connect it with the body. Encephal/o refers to brain, myel/o may refer to spinal cord or bone marrow depending on context, and mening/o identifies meninges. Afferent pathways carry information toward the central nervous system; efferent pathways carry output away. Paresthesia is an abnormal sensation, aphasia a language impairment, and ataxia impaired coordination. These terms must not be treated as synonyms for weakness.','Ophthalm/o and ocul/o concern the eye; ot/o concerns the ear. Otitis media involves the middle ear, while conjunctivitis involves the conjunctiva. Endocrine glands release hormones into blood, unlike exocrine glands that use ducts. Thyroid/o, adren/o, and pituitar/o identify glands. Hyperthyroidism and hypothyroidism describe excess and insufficient thyroid hormone activity. Diabetes mellitus concerns glucose regulation; diabetes insipidus concerns water balance and has a different mechanism. Shared naming is not proof of a shared disease process.', ['Explain why a person with aphasia may have difficulty naming an object even when vision and muscle strength are intact.','Aphasia describes impaired language processing, not necessarily blindness or paralysis. Visual input, language interpretation, and motor output are separate functions. The finding should be documented precisely and interpreted within the neurological assessment.'],[['Aphasia','A language impairment may affect expression, comprehension, or both.',['language','comprehension','expression']],['Afferent','Sensory input travels toward the central nervous system.',['sensory','toward']],['Efferent','Motor output travels away from the central nervous system.',['motor','away']]],['Which term concerns abnormal sensation?',['Paresthesia','Aphasia','Ataxia','Otitis'],'Paresthesia includes altered sensations such as tingling.'],['Which structure releases hormones into blood?',['Endocrine gland','Exocrine duct','Tendon','Bronchiole'],'Endocrine glands release hormones into circulation rather than through ducts.']],
 ['Reproductive terms and diagnostic procedures','Hyster/o and uter/o refer to uterus, oophor/o to ovary, salping/o to a tube, and cervic/o may refer to the uterine cervix or neck depending on context. Orchid/o and orchi/o identify testis, prostat/o prostate, and mamm/o breast. Obstetrics concerns pregnancy and childbirth; gynecology concerns the female reproductive system. A hysterectomy does not by definition include ovary removal. A bilateral salpingo-oophorectomy includes both fallopian tubes and ovaries, making each component meaningful.','Distinguish -scopy, visual examination; -graphy, recording process; -gram, the record; and -centesis, puncture to withdraw fluid. A biopsy obtains material for evaluation; it is not itself a diagnosis of cancer. Benign and malignant describe biological behavior, not simply the size of a mass. Use the exact procedure name when comparing alternatives. Abbreviations are context-dependent, and a guessed expansion can alter meaning. Build a final review table with organ, combining form, symptom, diagnostic procedure, and specialist rather than a single alphabetical word list.', ['A learner says hysterectomy means removal of ovaries and biopsy means cancer. Explain both errors.','Hysterectomy is removal of the uterus, whereas oophorectomy is removal of an ovary. Biopsy means obtaining tissue or cells for examination; pathology results determine what that material shows. Procedure terminology should not be mistaken for an outcome.'],[['Uterus','Hyster/o and uter/o identify the uterus, distinct from the ovaries.',['uterus','hyster']],['Ovary','Oophor/o identifies an ovary; -ectomy specifies removal.',['ovary','oophor']],['Biopsy','Sampling for examination does not by itself establish malignancy.',['sample','tissue','examin']]],['Which suffix means the recording process?',['-graphy','-gram','-ectomy','-algia'],'-graphy is a process, while -gram is the resulting record.'],['Which procedure removes an ovary?',['Oophorectomy','Hysterectomy','Cystoscopy','Amniocentesis'],'Oophor/o identifies ovary and -ectomy removal.']]
 ]]
]);
